	}

	v2Enabled := settings.IsCheckpointsV2Enabled(ctx)
	version := settings.CheckpointsVersion(ctx)
	localV2MainRef := false
	if version != 2 && !v2Enabled {
		localV2MainRef = hasLocalV2MainRef(repo)
	}
