			slog.String("session_id", sessionID),
			slog.String("agent", string(compactor.Name())),
		)
		return nil
	}
	if !bytes.HasSuffix(compacted.Transcript, []byte{'\n'}) {
		compacted.Transcript = append(compacted.Transcript, '\n')
