	if err := writeCommittedV2(ctx, repo, opts); err != nil {
		logging.Warn(ctx, "v2 dual-write failed",
			slog.String("checkpoint_id", opts.CheckpointID.String()),
			slog.String("error", err.Error()),
		)
	}
}

