380		msg, err := json.Marshal(inner)
381		if err != nil {
382			t.Fatalf("failed to marshal inner message: %v", err)
383		}
384		line := map[string]interface{}{
385			"type":    "message",
386			"id":      id,
387			"message": json.RawMessage(msg),
388		}
389		b, err := json.Marshal(line)
390		if err != nil {
391			t.Fatalf("failed to marshal droid line: %v", err)
392		}
