399		// Build a Droid transcript with non-message entries interspersed:
400		// Line 0: session_start (non-message)
401		// Line 1: user message (no tokens)
402		// Line 2: assistant message with 10 input, 20 output tokens
403		// Line 3: session_event (non-message)
404		// Line 4: assistant message with 5 input, 30 output tokens
405		transcript := "" +
406			`{"type":"session_start","id":"s1"}` + "\n" +
407			droidMessage(t, "m1", "user", nil) + "\n" +
408			droidMessage(t, "m2", "assistant", map[string]int{
409				"input_tokens": 10, "output_tokens": 20,
410			}) + "\n" +
411			`{"type":"session_event","data":"heartbeat"}` + "\n" +
412			droidMessage(t, "m3", "assistant", map[string]int{
413				"input_tokens": 5, "output_tokens": 30,
414			}) + "\n"
415	
416		data := []byte(transcript)
417	
418		// With startOffset=0: should count all messages (m2 + m3)
419		usageAll := calculateTokenUsage(agent.AgentTypeFactoryAIDroid, data, 0)
420		if usageAll.InputTokens != 15 {
421			t.Errorf("startOffset=0: InputTokens = %d, want 15", usageAll.InputTokens)
422		}
423		if usageAll.OutputTokens != 50 {
424			t.Errorf("startOffset=0: OutputTokens = %d, want 50", usageAll.OutputTokens)
425		}
426		if usageAll.APICallCount != 2 {
427			t.Errorf("startOffset=0: APICallCount = %d, want 2", usageAll.APICallCount)
428		}
429	
430		// With startOffset=3: skip lines 0-2 (session_start, m1, m2).
431		// Only line 3 (session_event, filtered) and line 4 (m3) remain.
432		// Should count only m3's tokens.
433		usageFrom3 := calculateTokenUsage(agent.AgentTypeFactoryAIDroid, data, 3)
434		if usageFrom3.InputTokens != 5 {
435			t.Errorf("startOffset=3: InputTokens = %d, want 5", usageFrom3.InputTokens)
436		}
437		if usageFrom3.OutputTokens != 30 {
438			t.Errorf("startOffset=3: OutputTokens = %d, want 30", usageFrom3.OutputTokens)
439		}
440		if usageFrom3.APICallCount != 1 {
441			t.Errorf("startOffset=3: APICallCount = %d, want 1", usageFrom3.APICallCount)
442		}
443	
444		// Regression: using the OLD buggy code would have parsed all messages (ignoring
445		// non-message entries), producing [m1, m2, m3], then sliced at index 3 which
446		// is out of bounds — returning all tokens instead of just m3's.
447		// With startOffset=1: skip only line 0 (session_start).
448		// Lines 1 (m1), 2 (m2), 3 (session_event, filtered), 4 (m3) remain.
449		usageFrom1 := calculateTokenUsage(agent.AgentTypeFactoryAIDroid, data, 1)
450		if usageFrom1.InputTokens != 15 {
451			t.Errorf("startOffset=1: InputTokens = %d, want 15", usageFrom1.InputTokens)
452		}
453		if usageFrom1.APICallCount != 2 {
454			t.Errorf("startOffset=1: APICallCount = %d, want 2", usageFrom1.APICallCount)
455		}
456	}
