18	// CommittedReader provides read access to committed checkpoint data.
19	// Both GitStore (v1) and V2GitStore (v2) implement this interface.
20	type CommittedReader interface {
21		ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)
22		ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
23	}
24	
25	// CommittedListReader provides read and list access to committed checkpoint data.
26	// GitStore, V2GitStore, and DualCheckpointReader implement this interface.
27	type CommittedListReader interface {
28		CommittedReader
29		ListCommitted(ctx context.Context) ([]CommittedInfo, error)
30		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*CommittedMetadata, error)
31		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)
32		ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error)
33	}
34	
35	// CommittedStore provides read/list access plus committed checkpoint metadata updates.
36	// NewCommittedReader returns this abstraction so callers do not need to know which
37	// backing checkpoint format was selected.
38	type CommittedStore interface {
39		CommittedListReader
40		UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error
41		GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error)
42	}
43	
44	// CommittedReaderOptions configures NewCommittedReader.
45	type CommittedReaderOptions struct {
46		BlobFetcher BlobFetchFunc
47	}
48	
49	func NewCommittedReader(_ context.Context, repo *git.Repository, opts CommittedReaderOptions) (CommittedStore, error) {
50		if repo == nil {
51			return nil, errors.New("git repository is required")
52		}
53	
54		v1Store := NewGitStore(repo)
55		if opts.BlobFetcher != nil {
56			v1Store.SetBlobFetcher(opts.BlobFetcher)
57		}
58	
59		if !HasLocalV2MainRef(repo) {
60			return v1Store, nil
61		}
62	
63		v2Store := NewV2GitStore(repo)
64		if opts.BlobFetcher != nil {
65			v2Store.SetBlobFetcher(opts.BlobFetcher)
66		}
67		return &DualCheckpointReader{v2: v2Store, v1: v1Store}, nil
68	}
