70	// HasLocalV2MainRef reports whether the v2 /main ref exists locally in repo.
71	// It is the only signal for whether to attempt v2 reads — v2 writes have been
72	// removed, so a repo only has the ref if it was created before v2 was
73	// disallowed or fetched from a remote that still has it.
74	func HasLocalV2MainRef(repo *git.Repository) bool {
75		if repo == nil {
76			return false
77		}
78		_, err := repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
79		return err == nil
80	}
