87	func (r *DualCheckpointReader) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
88		summary, err := r.v2.ReadCommitted(ctx, checkpointID)
89		if err == nil && summary != nil {
90			return summary, nil
91		}
92		if ctxErr := ctx.Err(); ctxErr != nil {
93			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
94		}
95		if err != nil {
96			logV2Fallback(ctx, "v2 ReadCommitted failed, falling back to v1", checkpointID, err)
97		}
98		return r.v1.ReadCommitted(ctx, checkpointID)
99	}
