101	func (r *DualCheckpointReader) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
102		content, err := r.v2.ReadSessionContent(ctx, checkpointID, sessionIndex)
103		if err == nil {
104			return content, nil
105		}
106		if ctxErr := ctx.Err(); ctxErr != nil {
107			return nil, ctxErr //nolint:wrapcheck // Propagating context cancellation
108		}
109		if errors.Is(err, ErrCheckpointNotFound) {
110			v2CheckpointExists, existsErr := r.v2CheckpointExists(ctx, checkpointID)
111			if existsErr != nil {
112				return nil, existsErr
113			}
114			if v2CheckpointExists {
115				summary, summaryErr := r.readV1FallbackSummary(ctx, checkpointID, err)
116				if summaryErr != nil {
117					return nil, summaryErr
118				}
119				if !hasSingleV1FallbackSession(summary, sessionIndex) {
120					return nil, err
121				}
122				return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
123			}
124			return r.readV1SessionContentByIndex(ctx, checkpointID, sessionIndex, err)
125		}
