// /full/*) or when a fetch remote URL is resolvable (so remote-only v2
// generations can still be retention-cleaned via checkpoint_remote or the
// fallback origin URL).
func hasV2RefsToClean(ctx context.Context) bool {
	if url, err := checkpointremote.FetchURL(ctx); err == nil && url != "" {
		return true
	}
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		return false
	}
	iter, err := repo.References()
	if err != nil {
		return false
	}
