	found := false
	_ = iter.ForEach(func(ref *plumbing.Reference) error {
		if strings.HasPrefix(string(ref.Name()), paths.V2FullRefPrefix) || string(ref.Name()) == paths.V2MainRefName {
			found = true
		}
		return nil
	})
	return found

