func parseCheckpointsVersion(val any) (int, bool) {
	v, ok := val.(int)
	if ok && (v == 1 || v == 2) {
		return v, true
	}
	floatV, ok := val.(float64)
	if ok && (floatV == 1 || floatV == 2) {
		return int(floatV), true
	}
	stringV, ok := val.(string)
	if ok {
		parsed, err := strconv.Atoi(stringV)
		if err == nil && (parsed == 1 || parsed == 2) {
			return parsed, true
		}
	}
	return 1, false
}

